    x = data[0] if len(data) > 0 else ''
    weights_line = data[1] if len(data) > 1 else ''

    weight_map = {}
    if weights_line.strip():
        tokens = weights_line.split()
        for tok in tokens:
            if ':' in tok:
                ch, val = tok.split(':', 1)
                try:
                    weight_map[ch] = int(val)
                except ValueError:
                    pass

    n = len(x)
    w = [weight_map.get(c, 0) for c in x]

    # prefix sums
    S = [0] * (n + 1)
    for idx in range(n):
        S[idx + 1] = S[idx] + w[idx]

    best_key = None
    best_i = 0
    best_j = 0

    for i in range(n + 1):
        for j in range(i, n + 1):
            s = S[j] - S[i]
            length = j - i
            key = (-s, i, length)
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
                best_j = j

    result = x[best_i:best_j]
    print(result)

