import sys, json

def to_str_repr(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    elif v is None:
        return "null"
    elif isinstance(v, str):
        return v
    else:
        # numbers (int or float)
        return json.dumps(v)

def main():
    raw = sys.stdin.read()
    data = json.loads(raw)
    if not isinstance(data, dict):
        raise ValueError("Input must be a JSON object")

    # Overwrite/add key 'a' with integer value 1
    data["a"] = 1

    # Compute frequency table, distinguishing by both value and type
    counts = {}
    for v in data.values():
        key = (type(v), v)
        counts[key] = counts.get(key, 0) + 1

    freq = {}
    for (t, v), c in counts.items():
        s = to_str_repr(v)
        # In case of collision (unlikely), sum counts (shouldn't happen given distinct type+value)
        freq[s] = freq.get(s, 0) + c

    result = {"data": data, "freq": freq}
    print(json.dumps(result, sort_keys=True))

