import sys, json, ast

def get_annotation_str(node):
    return ast.unparse(node)

def main():
    src = sys.stdin.read()
    tree = ast.parse(src)
    stmt = tree.body[0]
    result = {}
    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
        result['function_name'] = stmt.name
        result['is_lambda'] = False
        args_node = stmt.args
        params = list(args_node.posonlyargs) + list(args_node.args)
        arg_names = [a.arg for a in params]
        annotations = {}
        for a in params:
            if a.annotation is not None:
                annotations[a.arg] = get_annotation_str(a.annotation)
        if stmt.returns is not None:
            annotations['return'] = get_annotation_str(stmt.returns)
        defaults_nodes = args_node.defaults
        if defaults_nodes:
            defaults_values = [ast.literal_eval(d) for d in defaults_nodes]
        else:
            defaults_values = None
        result['args'] = arg_names
        result['defaults'] = defaults_values
        result['annotations'] = annotations
    elif isinstance(stmt, ast.Assign):
        target = stmt.targets[0]
        name = target.id
        lam = stmt.value
        if not isinstance(lam, ast.Lambda):
            raise ValueError('Expected lambda assignment')
        args_node = lam.args
        params = list(args_node.posonlyargs) + list(args_node.args)
        arg_names = [a.arg for a in params]
        defaults_nodes = args_node.defaults
        if defaults_nodes:
            defaults_values = [ast.literal_eval(d) for d in defaults_nodes]
        else:
            defaults_values = None
        result['function_name'] = name
        result['is_lambda'] = True
        result['args'] = arg_names
        result['defaults'] = defaults_values
        result['annotations'] = {}
    else:
        raise ValueError('Unsupported statement type: ' + str(type(stmt)))
    print(json.dumps(result))

