import re

TOKEN_RE = re.compile(r'\(.*?\)|\w+|[^\w]+')


def main():
    data = sys.stdin.read()
    # Strip one trailing newline (a trailing newline does not create an extra row)
    if data.endswith('\n'):
        data = data[:-1]
    if data == '':
        rows = []
    else:
        rows = data.split('\n')
    rows = [r[:-1] if r.endswith('\r') else r for r in rows]

    combined = ' '.join(rows)

    counts = {}
    order = []
    for m in TOKEN_RE.finditer(combined):
        tok = m.group(0)
        if tok in counts:
            counts[tok] += 1
        else:
            counts[tok] = 1
            order.append(tok)

    out = []
    for tok in order:
        out.append(str(counts[tok]) + '\t' + tok)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


