import sys, json

def tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '(':
            j = text.find(')', i)
            if j == -1:
                tokens.append(text[i:])
                i = n
            else:
                tokens.append(text[i:j+1])
                i = j + 1
        else:
            if c.isalnum() or c == '_':
                tokens.append(c)
            i += 1
    return tokens

